package io.rift.cronos;

import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.*;
import android.content.ContentValues;
import org.json.*;
import java.util.*;

/** Device-private, chain/account-scoped personal data. Namespace selection is NOT wallet authentication. */
public final class LocalWorkspace extends SQLiteOpenHelper {
    public LocalWorkspace(Context context){super(context,"rift-personal.sqlite",null,2);}
    @Override public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);}
    @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE documents(id TEXT PRIMARY KEY, account TEXT NOT NULL, title TEXT NOT NULL, document TEXT NOT NULL, version INTEGER NOT NULL, updated INTEGER NOT NULL)");db.execSQL("CREATE INDEX documents_account ON documents(account,updated)");db.execSQL("CREATE TABLE favorites(account TEXT NOT NULL,address TEXT NOT NULL,PRIMARY KEY(account,address))");db.execSQL("CREATE TABLE snapshots(account TEXT NOT NULL,cachekey TEXT NOT NULL,report TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(account,cachekey))");db.execSQL("CREATE TABLE receipts(account TEXT NOT NULL,hash TEXT NOT NULL,report TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(account,hash))");}
    @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){if(oldVersion==1&&newVersion==2){db.execSQL("CREATE TABLE snapshots(account TEXT NOT NULL,cachekey TEXT NOT NULL,report TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(account,cachekey))");return;}throw new IllegalStateException("Unsupported workspace schema upgrade; export before updating");}
    public static String account(String value){return value==null||value.trim().isEmpty()?"25:device":"25:"+ReadOnlyRpc.address(value.trim());}
    private void document(JSONObject value) throws Exception {if(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException("Draft limit is 64 KiB");noCredentials(value,0);}
    private void noCredentials(Object value,int depth) throws Exception {
        if(depth>24)throw new IllegalArgumentException("Draft nesting limit exceeded");
        if(value instanceof JSONObject){JSONObject object=(JSONObject)value;Iterator<String> keys=object.keys();while(keys.hasNext()){String key=keys.next(),flat=key.toLowerCase(Locale.ROOT).replace("_","").replace("-","");if(flat.matches(".*(privatekey|seedphrase|mnemonic|password|apikey|accesstoken|authorization|pinatajwt).*")||flat.equals("secret"))throw new IllegalArgumentException("Credential fields are not allowed in workspace exports");noCredentials(object.get(key),depth+1);}}
        else if(value instanceof JSONArray){JSONArray rows=(JSONArray)value;for(int i=0;i<rows.length();i++)noCredentials(rows.get(i),depth+1);}
    }
    private void profileBudget(SQLiteDatabase db,String account){WorkspacePolicy.account(account);try(Cursor c=db.rawQuery("SELECT COUNT(DISTINCT account) FROM (SELECT account FROM documents UNION SELECT account FROM favorites)",null)){c.moveToFirst();if(c.getInt(0)>=64){try(Cursor found=db.rawQuery("SELECT 1 FROM documents WHERE account=? UNION SELECT 1 FROM favorites WHERE account=?",new String[]{account,account})){if(!found.moveToFirst())throw new IllegalStateException("64 local profiles maximum; export/delete unused profiles");}}}}
    public String save(String account,String title,JSONObject value) throws Exception {
        document(value);if(title.trim().isEmpty()||title.length()>120)throw new IllegalArgumentException("Enter a title up to 120 characters");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{
        profileBudget(db,account);
        try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM documents WHERE account=?",new String[]{account})){c.moveToFirst();if(c.getInt(0)>=50)throw new IllegalStateException("50 drafts maximum per profile; export/delete old drafts");}
        String id=UUID.randomUUID().toString();ContentValues row=new ContentValues();row.put("id",id);row.put("account",account);row.put("title",title);row.put("document",value.toString());row.put("version",1);row.put("updated",System.currentTimeMillis());db.insertOrThrow("documents",null,row);db.setTransactionSuccessful();return id;}finally{db.endTransaction();}
    }
    public JSONArray drafts(String account) throws Exception {JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,title,document,version,updated FROM documents WHERE account=? ORDER BY updated DESC",new String[]{account})){while(c.moveToNext())rows.put(new JSONObject().put("id",c.getString(0)).put("title",c.getString(1)).put("document",new JSONObject(c.getString(2))).put("version",c.getInt(3)).put("updated",c.getLong(4)));}return rows;}
    public void delete(String account,String id){getWritableDatabase().delete("documents","account=? AND id=?",new String[]{account,id});}
    public void favorite(String account,String address,boolean add) throws Exception {
        address=ReadOnlyRpc.address(address);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{if(!add){db.delete("favorites","account=? AND address=?",new String[]{account,address});db.setTransactionSuccessful();return;}
        try(Cursor existing=db.rawQuery("SELECT 1 FROM favorites WHERE account=? AND address=?",new String[]{account,address})){if(existing.moveToFirst()){db.setTransactionSuccessful();return;}}
        profileBudget(db,account);
        try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM favorites WHERE account=?",new String[]{account})){c.moveToFirst();if(c.getInt(0)>=1000)throw new IllegalStateException("Favorite limit reached");}
        ContentValues row=new ContentValues();row.put("account",account);row.put("address",address);db.insertWithOnConflict("favorites",null,row,SQLiteDatabase.CONFLICT_IGNORE);db.setTransactionSuccessful();}finally{db.endTransaction();}
    }
    public JSONArray favorites(String account){JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT address FROM favorites WHERE account=? ORDER BY address",new String[]{account})){while(c.moveToNext())rows.put(c.getString(0));}return rows;}
    private void observationBudget(SQLiteDatabase db,String account){WorkspacePolicy.account(account);try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM (SELECT account FROM snapshots UNION SELECT account FROM receipts)",null)){c.moveToFirst();if(c.getInt(0)>=64)try(Cursor found=db.rawQuery("SELECT 1 FROM snapshots WHERE account=? UNION SELECT 1 FROM receipts WHERE account=?",new String[]{account,account})){if(!found.moveToFirst())throw new IllegalStateException("Observation profile limit reached");}}}
    public void receipt(String account,String hash,JSONObject report)throws Exception{hash=ReadPolicy.hash(hash);if(report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException("Receipt observation limit exceeded");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{observationBudget(db,account);ContentValues row=new ContentValues();row.put("account",account);row.put("hash",hash);row.put("report",report.toString());row.put("updated",System.currentTimeMillis());db.insertWithOnConflict("receipts",null,row,SQLiteDatabase.CONFLICT_REPLACE);db.execSQL("DELETE FROM receipts WHERE account=? AND hash NOT IN (SELECT hash FROM receipts WHERE account=? ORDER BY updated DESC LIMIT 50)",new Object[]{account,account});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    public JSONArray receipts(String account) throws Exception {JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT report FROM receipts WHERE account=? ORDER BY updated DESC LIMIT 50",new String[]{account})){while(c.moveToNext())rows.put(new JSONObject(c.getString(0)));}return rows;}
    public void snapshot(String account,String key,JSONObject report)throws Exception{if(key==null||key.length()>256||report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException("Snapshot limit exceeded");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{observationBudget(db,account);ContentValues row=new ContentValues();row.put("account",account);row.put("cachekey",key);row.put("report",report.toString());row.put("updated",System.currentTimeMillis());db.insertWithOnConflict("snapshots",null,row,SQLiteDatabase.CONFLICT_REPLACE);db.execSQL("DELETE FROM snapshots WHERE account=? AND cachekey NOT IN (SELECT cachekey FROM snapshots WHERE account=? ORDER BY updated DESC LIMIT 50)",new Object[]{account,account});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    public JSONArray snapshots(String account) throws Exception {JSONArray rows=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT report,updated FROM snapshots WHERE account=? ORDER BY updated DESC LIMIT 50",new String[]{account})){while(c.moveToNext())rows.put(new JSONObject().put("cached",true).put("checkedAt",c.getLong(1)).put("report",new JSONObject(c.getString(0))).put("warning","Historical local observation, not current ownership/order validity"));}return rows;}
    public JSONObject backup(String account) throws Exception {return new JSONObject().put("format","rift-personal-workspace").put("schema",1).put("chainId",25).put("account",account).put("drafts",drafts(account)).put("favorites",favorites(account)).put("note","Personal drafts/favorites only. No credentials, wallet keys, on-chain cancellations or automatic cloud sync. File is NOT encrypted.");}
    public int restore(String account,JSONObject backup) throws Exception {
        if(!"rift-personal-workspace".equals(backup.opt("format"))||!(backup.opt("schema") instanceof Number)||((Number)backup.get("schema")).doubleValue()!=1||!(backup.opt("chainId") instanceof Number)||((Number)backup.get("chainId")).doubleValue()!=25||!account.equals(backup.opt("account")))throw new IllegalArgumentException("Backup format, chain or selected profile mismatch");
        JSONArray docs=backup.getJSONArray("drafts"),favorites=backup.getJSONArray("favorites");if(docs.length()>50||favorites.length()>1000)throw new IllegalArgumentException("Backup limits exceeded");
        for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);document(d.getJSONObject("document"));if(!(d.get("title") instanceof String))throw new IllegalArgumentException("Invalid title");if(d.getString("title").trim().isEmpty()||d.getString("title").length()>120)throw new IllegalArgumentException("Invalid title");}
        for(int i=0;i<favorites.length();i++)ReadOnlyRpc.address(favorites.getString(i));
        SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);save(account,d.getString("title"),d.getJSONObject("document"));}for(int i=0;i<favorites.length();i++)favorite(account,favorites.getString(i),true);db.setTransactionSuccessful();return docs.length();}finally{db.endTransaction();}
    }
    public void clear(String account){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{for(String table:new String[]{"documents","favorites","receipts","snapshots"})db.delete(table,"account=?",new String[]{account});db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
